package kr.workbench;
import java.util.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.zip.*;import java.util.regex.Pattern;
/** Portable evidence with credentials redacted. Raw bodies are excluded unless explicitly selected. */
final class BountyEvidence {
 record Item(String label,String method,String url,String request,String response,String note,String account){Item(String label,String method,String url,String request,String response,String note){this(label,method,url,request,response,note,"");}}
 static final Pattern SECRET=Pattern.compile("(?i)(password|passwd|secret|token|authorization|api[-_]?key|csrf|xsrf|session|cookie|credential)");
 static String esc(String s){return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;");}
 static String packet(String raw,Set<String> extra,Collection<String> secrets,boolean bodies){
  String s=Objects.toString(raw,"");if(s.length()>128*1024)s=s.substring(0,128*1024);s=s.replace("\r\n","\n");int split=s.indexOf("\n\n");String head=split<0?s:s.substring(0,split),body=split<0?"":s.substring(split+2);StringBuilder out=new StringBuilder();String type="";for(String line:head.split("\n"))if(line.toLowerCase(Locale.ROOT).startsWith("content-type:"))type=line.substring(13).strip().split(";",2)[0].toLowerCase(Locale.ROOT);
  for(String line:head.split("\n",-1)){int colon=line.indexOf(':');if(colon>0&&(SECRET.matcher(line.substring(0,colon)).find()||extra.contains(line.substring(0,colon).toLowerCase(Locale.ROOT))))line=line.substring(0,colon)+": [REDACTED]";
   line=line.replaceAll("([?#&][^=\\s&]+)=([^\\s&]*)","$1=[REDACTED]");out.append(line).append('\n');}
  out.append('\n');if(!body.isEmpty()){if(!bodies)out.append("[본문 제외 · 재현 시 원본을 로컬에서 확인]");else if(type.equals("application/x-www-form-urlencoded")){try{StringJoiner form=new StringJoiner("&");for(String pair:body.split("&",-1)){String[] p=pair.split("=",2);String key=java.net.URLDecoder.decode(p[0],StandardCharsets.UTF_8),value=java.net.URLDecoder.decode(p.length==2?p[1]:"",StandardCharsets.UTF_8);value=SECRET.matcher(key).find()||fragments(secrets).contains(value)?"[REDACTED]":known(value,secrets);form.add(java.net.URLEncoder.encode(key,StandardCharsets.UTF_8)+"="+java.net.URLEncoder.encode(value,StandardCharsets.UTF_8));}out.append(form);}catch(Exception ex){out.append("[폼 디코딩 실패 · 본문 제외]");}}else try{out.append(MetadataExport.json(scrub(MinerJson.parse(body,128*1024,20000),"",fragments(secrets))));}catch(Exception e){out.append("[비 JSON 본문 제외 · 바이트 수/해시로 원본 확인]");}}
  return known(out.toString(),secrets);
 }
 static Set<String> fragments(Collection<String> secrets){Set<String> out=new HashSet<>();for(String value:secrets){if(value==null||value.isEmpty())continue;out.add(value);if(value.matches("(?i)Bearer .+|Basic .+"))out.add(value.substring(value.indexOf(' ')+1));for(String pair:value.split(";")){int n=pair.indexOf('=');if(n>0&&!pair.substring(n+1).strip().isEmpty())out.add(pair.substring(n+1).strip());}}return out;}
 static Object scrub(Object value,String key){return scrub(value,key,Set.of());}
 static Object scrub(Object value,String key,Set<String> secrets){if(SECRET.matcher(key).find()||value instanceof String text&&secrets.contains(text))return "[REDACTED]";if(value instanceof Map<?,?> m){Map<String,Object> out=new LinkedHashMap<>();m.forEach((k,v)->out.put(k.toString(),scrub(v,k.toString(),secrets)));return out;}if(value instanceof List<?> l)return l.stream().map(v->scrub(v,key,secrets)).toList();return value;}
 static String known(String s,Collection<String> secrets){Set<String> values=new LinkedHashSet<>();for(String value:secrets){if(value==null)continue;values.add(value);if(value.matches("(?i)Bearer .+|Basic .+"))values.add(value.substring(value.indexOf(' ')+1));for(String pair:value.split(";")){int n=pair.indexOf('=');if(n>0)values.add(pair.substring(n+1).strip());}}for(String v:values.stream().filter(v->v.length()>=4).sorted(Comparator.comparingInt(String::length).reversed()).toList())s=s.replace(v,"[REDACTED]");return s;}
 static String validateImage(Path image)throws Exception{if(Files.size(image)>8*1024*1024)throw new IllegalArgumentException("브라우저 이미지 8MB 제한");try(var in=javax.imageio.ImageIO.createImageInputStream(image.toFile())){if(in==null)throw new IllegalArgumentException("이미지 읽기 실패");var readers=javax.imageio.ImageIO.getImageReaders(in);if(!readers.hasNext())throw new IllegalArgumentException("PNG/JPEG 이미지 필요");var r=readers.next();try{r.setInput(in);String f=r.getFormatName().toLowerCase(Locale.ROOT);if(!Set.of("png","jpeg","jpg").contains(f)||r.getWidth(0)>4096||r.getHeight(0)>4096)throw new IllegalArgumentException("PNG/JPEG 최대 4096 픽셀");r.read(0);return f.equals("png")?"png":"jpg";}finally{r.dispose();}}}
 static void save(Path path,String title,String impact,String steps,List<Item> items,Set<String> headers,Collection<String> secrets,boolean bodies,String coverage,Path image)throws Exception{save(path,title,impact,steps,items,headers,secrets,bodies,coverage,image,List.of());}
 static void save(Path path,String title,String impact,String steps,List<Item> items,Set<String> headers,Collection<String> secrets,boolean bodies,String coverage,Path image,List<Map<String,Object>> oast)throws Exception{
  if(items.isEmpty())throw new IllegalArgumentException("증거 요청을 먼저 가져오세요.");if(items.size()>32||title.length()>256||impact.length()>8192||steps.length()>8192)throw new IllegalArgumentException("증거 크기 제한");
  StringBuilder md=new StringBuilder("# "+known(title,secrets)+"\n\n## 영향 (진단자 작성)\n"+known(impact,secrets)+"\n\n## 재현 절차\n"+known(steps,secrets)+"\n\n");StringBuilder web=new StringBuilder("<!doctype html><html lang=ko><meta charset=utf-8><title>점검 증거</title><style>body{font-family:system-ui;max-width:1100px;margin:40px auto;padding:20px}pre{white-space:pre-wrap;background:#f0f5f8;padding:18px}h2{color:#126078}</style><h1>"+esc(known(title,secrets))+"</h1><h2>영향</h2><pre>"+esc(known(impact,secrets))+"</pre><h2>재현 절차</h2><pre>"+esc(known(steps,secrets))+"</pre>");
  List<Map<String,String>> metadata=new ArrayList<>();Map<String,byte[]> files=new LinkedHashMap<>();int i=0;
  for(Item item:items){String request=packet(item.request,headers,secrets,bodies),response=packet(item.response,headers,secrets,bodies),label=known(item.label,secrets),note=known(item.note,secrets),url=known(Objects.toString(ActivityTracker.safeUrl(item.url),""),secrets);i++;
   files.put("requests/"+i+".http",request.getBytes(StandardCharsets.UTF_8));files.put("responses/"+i+".http",response.getBytes(StandardCharsets.UTF_8));metadata.add(Map.of("label",label,"method",item.method,"url",url,"note",note,"requestTextSha256",Core.hash(Objects.toString(item.request,"").getBytes(StandardCharsets.UTF_8)),"responseTextSha256",Core.hash(Objects.toString(item.response,"").getBytes(StandardCharsets.UTF_8)),"requestUtf8Bytes",String.valueOf(Objects.toString(item.request,"").getBytes(StandardCharsets.UTF_8).length),"responseUtf8Bytes",String.valueOf(Objects.toString(item.response,"").getBytes(StandardCharsets.UTF_8).length),"packetRepresentation","가린 텍스트 미리보기 · 원본 HTTP 바이트가 아님","accountId",item.account));
   md.append("## ").append(i).append(". ").append(label).append("\n").append(item.method).append(' ').append(url).append("\n\n").append(note).append("\n\n요청: requests/").append(i).append(".http\n응답: responses/").append(i).append(".http\n\n");web.append("<h2>").append(i).append(". ").append(esc(label)).append("</h2><p>").append(esc(item.method+" "+url)).append("</p><p>").append(esc(note)).append("</p><h3>요청</h3><pre>").append(esc(request)).append("</pre><h3>응답</h3><pre>").append(esc(response)).append("</pre>");}
  md.append("\n자동 관찰은 후보이며 진단자가 실제 영향과 재현 결과를 확인해야 합니다. 인증값·쿼리값은 가려져 있으므로 재현 시 로컬 원본으로 보완하세요.\n");
  files.put("report.md",md.toString().getBytes(StandardCharsets.UTF_8));files.put("report.html",web.toString().getBytes(StandardCharsets.UTF_8));files.put("evidence.json",MetadataExport.json(Map.of("version","0.22.1","items",metadata)).getBytes(StandardCharsets.UTF_8));files.put("coverage.json",known(coverage,secrets).getBytes(StandardCharsets.UTF_8));
  List<Map<String,Object>> linked=new ArrayList<>();for(var event:oast){Map<String,Object> row=new LinkedHashMap<>(event);List<Integer> refs=new ArrayList<>();for(int n=0;n<items.size();n++)if(Objects.equals(event.get("method"),items.get(n).method)&&Objects.equals(ActivityTracker.safeUrl(Objects.toString(event.get("url"),"")),ActivityTracker.safeUrl(items.get(n).url)))refs.add(n+1);row.put("evidenceItems",refs);row.put("correlation","제공 URL/메서드 연결 · 해당 패킷이 콜백을 유발했는지 수동 확인");linked.add(row);}files.put("oast.json",known(MetadataExport.json(linked),secrets).getBytes(StandardCharsets.UTF_8));
  if(image!=null){String format=validateImage(image);files.put("browser-evidence."+format,Files.readAllBytes(image));}
  Path temp=Files.createTempFile(path.toAbsolutePath().getParent(),"wb-evidence-",".tmp");try{try(ZipOutputStream zip=new ZipOutputStream(Files.newOutputStream(temp))){for(var f:files.entrySet()){zip.putNextEntry(new ZipEntry(f.getKey()));zip.write(f.getValue());zip.closeEntry();}}Files.move(temp,path,StandardCopyOption.REPLACE_EXISTING);}finally{Files.deleteIfExists(temp);}
 }
}
